      if (pcm == NULL)
        {
          return 1;
        }

      kws_engine_init(on_detect, NULL);
      if (argc >= 4)
        {
          kws_engine_set_threshold((float)atof(argv[3]));
        }

      g_detections = 0;
      stream(pcm, n);
      report(argv[2]);
      free(pcm);
      return 0;
    }

  if (argc >= 4 && strcmp(argv[1], "batch") == 0)
    {
      int expect = atoi(argv[3]);
      DIR *d = opendir(argv[2]);
      struct dirent *e;
      int total = 0;
      int hit = 0;
      int events = 0;
      double sum_first = 0.0;

      if (d == NULL)
        {
