             total ? 100.0 * hit / total : 0.0, events);
      if (hit)
        {
          printf(", mean first-prob %.3f", sum_first / hit);
        }

      printf("\n");
      return 0;
    }

  fprintf(stderr,
          "usage: %s golden | wav <f.wav> [thr] | batch <dir> <0|1> [thr]\n",
