  if (len >= 8 && strncmp(cmd, "KWS_INFO", 8) == 0)
    {
      kws_engine_get_stats(&st);
      return snprintf(rsp, rsplen,
                      "KWS on=%d thr=0.%03u frames=%lu inf=%lu det=%lu "
                      "last=0.%03u smooth=0.%03u peak=0.%03u us=%lu "
                      "drop=%lu\n",
