                      (unsigned long)(po * 1e6f + 0.5f));
    }

  if (len >= 8 && strncmp(cmd, "KWS_PEEK", 8) == 0)
    {
      int16_t pk;
      float f[3];

      kws_engine_peek(&pk, f);
      return snprintf(rsp, rsplen,
                      "KWS peek pcm=%d f0=%d f10=%d f39=%d (milli)\n",
                      (int)pk, (int)(f[0] * 1000.0f),
                      (int)(f[1] * 1000.0f), (int)(f[2] * 1000.0f));
